    Vcols=set(c for r in range(H) for c,x in enumerate(I[r]) if x==line) - set(c for row in hrows for c in row if I[row][c]==line)
    def step(rows,cells):
        rs=sorted(cells); return (rs[1]-rs[0]) if len(rs)==2 else None
    sr=(max(r for r in hrows)-min(r in hrows))//len(hrows) if hrows else None
    sc=(max(Vcols)-min(Vcols))//len(Vcols) if Vcols else None
