    for x,cl in pts.items():
        for key,lst in [('row',byrow[x]),('col',bycol[x])]:
            S = sr if key=='row' else sc
            spts=sorted(lst)
            if len(spts)>=2 and S and (spts[1]-spts[0])==S:
                for p in range(len(spts)+1):
